import React from 'react';
import { join } from 'path';
import {
  Document, Page, View, Text, Image, StyleSheet, Font, renderToBuffer,
} from '@react-pdf/renderer';

/* ---- Fonts (Poppins + Inter + Plus Jakarta Sans from @fontsource) ---- */
let fontsRegistered = false;
function ff(pkg: string, file: string): string {
  return join(process.cwd(), 'node_modules', '@fontsource', pkg, 'files', file);
}
function registerFonts(): void {
  if (fontsRegistered) return;
  Font.register({
    family: 'Poppins',
    fonts: [
      { src: ff('poppins', 'poppins-latin-600-normal.woff'), fontWeight: 600 },
      { src: ff('poppins', 'poppins-latin-700-normal.woff'), fontWeight: 700 },
    ],
  });
  Font.register({
    family: 'Inter',
    fonts: [{ src: ff('inter', 'inter-latin-400-normal.woff'), fontWeight: 400 }],
  });
  Font.register({
    family: 'Plus Jakarta Sans',
    fonts: [
      { src: ff('plus-jakarta-sans', 'plus-jakarta-sans-latin-400-normal.woff'), fontWeight: 400 },
      { src: ff('plus-jakarta-sans', 'plus-jakarta-sans-latin-600-normal.woff'), fontWeight: 600 },
      { src: ff('plus-jakarta-sans', 'plus-jakarta-sans-latin-700-normal.woff'), fontWeight: 700 },
    ],
  });
  Font.registerHyphenationCallback((w) => [w]);
  fontsRegistered = true;
}

/* ---- Background pages (design figé, variables laissées vides) ---- */
const BG1 = 'data:image/png;base64,';
const BG2 = join(process.cwd(), 'public', 'images', 'proposal-mechanism.png');
const BG3 = join(process.cwd(), 'public', 'images', 'proposal-investment.png');

export type ProposalPdfInput = {
  client: string;
  date?: string;
  offerName?: string;
  price?: string;
  currency?: string;
  period?: string;
  adBudget?: string;
};

const LOGO = join(process.cwd(), 'public', 'images', '63AgencyTextwhit.png');

const PAGE = { width: 1280, height: 720 } as const;
const styles = StyleSheet.create({
  page: { position: 'relative', width: 1280, height: 720 },
  bg: { position: 'absolute', top: 0, left: 0, width: 1280, height: 720 },
  /** Covers the small baked-in logo on the background art. */
  logoCover: {
    position: 'absolute',
    left: 40,
    top: 22,
    width: 230,
    height: 58,
    backgroundColor: '#0B0B0B',
  },
  /** Larger replacement logo (public/images/63AgencyTextwhit.png). */
  logo: {
    position: 'absolute',
    left: 52,
    top: 28,
    width: 280,
    height: 58,
  },
  client: { position: 'absolute', left: 85, top: 553, fontFamily: 'Plus Jakarta Sans', fontWeight: 700, fontSize: 30, color: '#F3F1EA', letterSpacing: 0.6, lineHeight: 1, textTransform: 'uppercase' },
  date: { position: 'absolute', left: 64, top: 656, fontFamily: 'Poppins', fontWeight: 600, fontSize: 11, color: '#8D897F', letterSpacing: 3.3, lineHeight: 1 },
  offer: { position: 'absolute', left: 97, top: 348, fontFamily: 'Poppins', fontWeight: 700, fontSize: 30, color: '#F3F1EA', lineHeight: 1 },
  amt: { position: 'absolute', right: 97, top: 338, textAlign: 'right', fontFamily: 'Poppins', fontWeight: 700, fontSize: 48, color: '#DEA65C', letterSpacing: 0.48, lineHeight: 1 },
  cur: { fontFamily: 'Poppins', fontWeight: 600, fontSize: 19, color: '#CFCCC3' },
  period: { position: 'absolute', right: 97, top: 396, textAlign: 'right', fontFamily: 'Poppins', fontWeight: 600, fontSize: 11, color: '#8D897F', letterSpacing: 2.64, lineHeight: 1 },
  budget: { position: 'absolute', left: 330, top: 470, width: 860, fontFamily: 'Inter', fontWeight: 400, fontSize: 13, color: '#CFCCC3', lineHeight: 1 },
  foot: { position: 'absolute', left: 120, top: 678, fontFamily: 'Plus Jakarta Sans', fontWeight: 600, fontSize: 11, color: '#6F6C64', letterSpacing: 2.2, lineHeight: 1 },
});

export async function renderProposalPdf(input: ProposalPdfInput): Promise<Buffer> {
  registerFonts();
  const d = {
    client: input.client || '',
    date: input.date || 'OCT 2026',
    offerName: input.offerName || '3-Month Partnership',
    price: input.price || '13 500,00',
    currency: input.currency || 'DHS',
    period: input.period || 'PER TRIMESTER',
    adBudget:
      input.adBudget ||
      'Les dépenses publicitaires restent à la charge de l\u2019entreprise cliente, avec un budget initial minimum de 3 000 DHS/mois.',
  };
  const foot = `Confidential proposal \u2014 Prepared for ${d.client} \u00B7 ${d.date}`.toUpperCase();

  const doc = React.createElement(
    Document,
    null,
    React.createElement(
      Page,
      { size: PAGE, style: styles.page },
      React.createElement(Image, { src: BG1, style: styles.bg }),
      React.createElement(View, { style: styles.logoCover }),
      React.createElement(Image, { src: LOGO, style: styles.logo }),
      React.createElement(Text, { style: styles.client }, (d.client || '').toUpperCase()),
      React.createElement(Text, { style: styles.date }, (d.date || '').toUpperCase()),
    ),
    React.createElement(
      Page,
      { size: PAGE, style: styles.page },
      React.createElement(Image, { src: BG2, style: styles.bg }),
      React.createElement(View, { style: styles.logoCover }),
      React.createElement(Image, { src: LOGO, style: styles.logo }),
    ),
    React.createElement(
      Page,
      { size: PAGE, style: styles.page },
      React.createElement(Image, { src: BG3, style: styles.bg }),
      React.createElement(View, { style: styles.logoCover }),
      React.createElement(Image, { src: LOGO, style: styles.logo }),
      React.createElement(Text, { style: styles.offer }, d.offerName),
      React.createElement(
        Text,
        { style: styles.amt },
        d.price,
        React.createElement(Text, { style: styles.cur }, d.currency),
      ),
      React.createElement(Text, { style: styles.period }, (d.period || '').toUpperCase()),
      React.createElement(Text, { style: styles.budget }, d.adBudget),
      React.createElement(Text, { style: styles.foot }, foot),
    ),
  );
  return renderToBuffer(doc);
}
